'use strict';
const assert = require('node:assert/strict');
const api = require('./solution');
assert.deepEqual(Object.keys(api).sort(), ['HandlerRegistry']);
const { HandlerRegistry } = api;

const registry = new HandlerRegistry();
assert.equal(registry.has('work'), false);
const first = function (a, b) {
  'use strict';
  assert.equal(this, undefined);
  return a + b;
};
assert.strictEqual(registry.register('work', first), registry);
assert.equal(registry.has('work'), true);
assert.equal(registry.invoke('work', 2, 3), 5);

const replacement = function (value) {
  'use strict';
  assert.equal(this, undefined);
  return value * 4;
};
assert.strictEqual(registry.register('work', replacement), registry);
assert.equal(registry.has('work'), true);
assert.equal(registry.invoke('work', 5), 20);

assert.equal(registry.unregister('work'), true);
assert.equal(registry.has('work'), false);
assert.throws(() => registry.invoke('work'), RangeError);
assert.equal(registry.unregister('work'), false);

registry.register('undefined-result', () => undefined);
assert.equal(registry.has('undefined-result'), true);
assert.equal(registry.invoke('undefined-result'), undefined);

registry.register('one', () => 1).register('two', () => 2);
assert.equal(registry.invoke('one'), 1);
assert.equal(registry.invoke('two'), 2);
assert.equal(registry.unregister('one'), true);
assert.equal(registry.has('two'), true);

for (const badName of ['', 1, null, undefined, {}, []]) {
  assert.throws(() => registry.register(badName, () => {}), TypeError);
  assert.throws(() => registry.unregister(badName), TypeError);
  assert.throws(() => registry.has(badName), TypeError);
  assert.throws(() => registry.invoke(badName), TypeError);
}
for (const badHandler of [null, {}, 'fn', 1]) {
  assert.throws(() => registry.register('bad', badHandler), TypeError);
}
assert.throws(() => registry.invoke('absent'), RangeError);

